  const a = rgb2hsl(color)
  const h = a[0]
  const s = n2p(a[1])
  const l = n2p(a[2])
  return color.a < 255 ? `hsla(${h}, ${s}%, ${l}%, ${b2n(color.a)})` : `hsl(${h}, ${s}%, ${l}%)`
}
